using System.Text.Json;
using Norse.Infrastructure.Backend.Keys;
using Xunit.MicrosoftTestingPlatform;
using Xunit.Runner.InProc.SystemConsole;

namespace Norse.Infrastructure.Backend.Tests;

/// <summary>
///     The test host's entry point (<c>XunitAutoGeneratedEntryPoint</c> is off in the csproj): xUnit's generated
///     dispatch, verbatim, plus three child-process modes — <c>--lock-holder {path}</c>,
///     <c>--destroy {root} {subjectId}</c>, and <c>--get-or-create {root} {subjectId}</c> — so the cross-process
///     tests launch this same assembly as the child, exercising the exact code under test, with no second project.
/// </summary>
static class Program
{
	static int Main(string[] args) =>
		args switch
		{
			["--lock-holder", var path] => HoldLock(path),
			["--destroy", var root, var subjectId] => DestroyAsync(root, Guid.Parse(subjectId))
				.GetAwaiter()
				.GetResult(),
			["--get-or-create", var root, var subjectId] => GetOrCreateAsync(root, Guid.Parse(subjectId))
				.GetAwaiter()
				.GetResult(),
			_ when args.Any(arg => arg is "-automated" or "@@") => ConsoleRunner.Run(args).GetAwaiter().GetResult(),
			_ => TestPlatformTestFramework.RunAsync(args, SelfRegisteredExtensions.AddSelfRegisteredExtensions)
				.GetAwaiter()
				.GetResult()
		};

	/// <summary>
	///     Takes the platform lock on <paramref name="path" />, reports <c>HELD</c> or <c>REFUSED</c> on stdout,
	///     and holds until stdin closes.
	/// </summary>
	static int HoldLock(string path)
	{
		using var held = IFileLockPrimitive.ForCurrentPlatform().TryAcquire(path);
		Console.WriteLine(held is null ? "REFUSED" : "HELD");
		Console.Out.Flush();
		_ = Console.In.ReadToEnd();
		return held is null ? 1 : 0;
	}

	/// <summary>
	///     Opens the store at <paramref name="root" />, reports <c>READY</c>, waits for one line on stdin (the
	///     start signal), destroys <paramref name="subjectId" />, and reports <c>RECEIPT {json}</c>: the receipt
	///     serialized exactly as the store writes it, so the parent compares bytes with the stored file.
	/// </summary>
	static async Task<int> DestroyAsync(string root, Guid subjectId, CancellationToken cancellationToken = default)
	{
		DevelopmentSubjectKeyStore store = new(root);
		await Console.Out.WriteLineAsync("READY".AsMemory(), cancellationToken);
		await Console.Out.FlushAsync(cancellationToken);
		_ = await Console.In.ReadLineAsync(cancellationToken);

		var receipt = await store.DestroyAsync(subjectId, cancellationToken);
		await Console.Out.WriteLineAsync($"RECEIPT {JsonSerializer.Serialize(new(receipt.ReceiptId, receipt.SeveredAt),
			KeysJsonContext.Default.ReceiptDocument)}".AsMemory(), cancellationToken);
		await Console.Out.FlushAsync(cancellationToken);
		return 0;
	}

	/// <summary>
	///     Opens the store at <paramref name="root" />, reports <c>READY</c>, waits for one line on stdin (the
	///     start signal), gets or creates <paramref name="subjectId" />'s key, and reports <c>KEY {base64}</c>.
	/// </summary>
	static async Task<int> GetOrCreateAsync(string root, Guid subjectId, CancellationToken cancellationToken = default)
	{
		DevelopmentSubjectKeyStore store = new(root);
		await Console.Out.WriteLineAsync("READY".AsMemory(), cancellationToken);
		await Console.Out.FlushAsync(cancellationToken);
		_ = await Console.In.ReadLineAsync(cancellationToken);

		var key = await store.GetOrCreateAsync(subjectId, cancellationToken);
		await Console.Out.WriteLineAsync($"KEY {Convert.ToBase64String(key)}".AsMemory(), cancellationToken);
		await Console.Out.FlushAsync(cancellationToken);
		return 0;
	}
}
